from taf.ul.bts_kpi_report_generator.converter.ErrorsHandlerToolsHolder import ErrorsHandlerToolsHolder


class DoubleAsteriskError(ErrorsHandlerToolsHolder):
    """
    Class for handling wrong double asterisk error .
    """

    def __init__(self, source_file_path, release):
        ErrorsHandlerToolsHolder.__init__(self, source_file_path, release)

    def handle_double_asterisk_error(self, i, nested, kpi_id, xlsx_formula):
        """
        Finds, and if found, fixes double unintended asterisk error in KPI's formula

        :param i: current char being analyzed
        :param nested: analyzed kpi's data
        :param kpi_id: analyzed kpi ID
        :param xlsx_formula: analyzed formula

        :return: corrected formula
        """
        try:
            if self.__find_contiguous_asterixs(nested["FORMULA"][i:]):

                self.ErrorsPrinter.warn_print("Double * in formula ?", "{} : {}{}{}{}{}".format(
                    kpi_id,
                    nested["FORMULA"][:i],
                    self.colors["<yel>"],
                    nested["FORMULA"][i],
                    self.colors["</yel>"],
                    nested["FORMULA"][i + 1:]
                ))
                self.logger.warning("Double * in formula {} : {}".format(kpi_id, nested["FORMULA"]))
                xlsx_formula = xlsx_formula[:i + self.adjustment] + " " + xlsx_formula[i + 1 + self.adjustment:]
                spaces_after_asterix = self.first_non_blank_space(xlsx_formula[i + self.adjustment:])
                if not any("Double asterisk" in error for error in self.found_errors):
                    self.found_errors.append(
                        "Double asterisk in formula (Formula may containt double asterisk ** which may lead to evaluating wrong value)")

                self.ErrorsPrinter.info_print("Attempt to repair the formula", "{} : {}{}{}{}{}".format(
                    kpi_id,
                    xlsx_formula[:i + self.adjustment + spaces_after_asterix],
                    self.colors["<gr>"],
                    xlsx_formula[i + spaces_after_asterix + self.adjustment],
                    self.colors["</gr>"],
                    xlsx_formula[i + spaces_after_asterix + 1 + self.adjustment:]
                ))
                self.logger.info("Attempt to repair the formula {} : {}".format(kpi_id, xlsx_formula))
        except Exception as other_errors:
            print("{} occured when trying to examin the {} formula in order to find double asterisk error".format(
                other_errors,
                kpi_id
            ))
            self.logger.warning("{} occured when trying to examin the {} formula in order to find double asterisk error".format(
                other_errors,
                kpi_id
            ))
        return xlsx_formula

    @staticmethod
    def __find_contiguous_asterixs(remaining_part_of_the_formula):
        """
        Check if first two first corresponding non whitespace characters are asterisks

        :param remaining_part_of_the_formula: Part of the formula that has not been examined yet

        :return: True or False
        """
        first_char = remaining_part_of_the_formula[0]
        if first_char != "*":
            return False
        for i, char in enumerate(remaining_part_of_the_formula[1:]):
            if char == " ":
                continue
            elif str((first_char + char)) == "**":
                return True
            break
        return False
